import java.util.List;

class Bounds {
    // one bound: extends, even for an interface
    static <T extends Comparable<T>> T maxOf2(T a, T b) {
        return a.compareTo(b) >= 0 ? a : b;
    }

    // two bounds with &: the class (if any) must come first
    static <T extends CharSequence & Comparable<T>> T shortest(List<T> items) {
        T best = items.get(0);
        for (T item : items) {
            if (item.length() < best.length()) best = item;
        }
        return best;
    }

    // no way to say "not null": T may always be null
    static <T> T firstOrThrow(List<T> items) {
        return items.get(0);   // could be null
    }
}

