// one bound: a colon
fun <T : Comparable<T>> maxOf2(a: T, b: T): T = if (a >= b) a else b

// two bounds: a where clause, in any order, at most one class
fun <T> shortest(items: List<T>): T where T : CharSequence, T : Comparable<T> {
    var best = items[0]
    for (item in items) {
        if (item.length < best.length) best = item
    }
    return best
}

// T : Any rules out nullable type arguments
fun <T : Any> firstOrThrow(items: List<T>): T = items[0]   // never null

