class Window<T extends Comparable<? super T>> {
    final T start, endInclusive;

    Window(T start, T endInclusive) {
        if (start.compareTo(endInclusive) > 0) throw new IllegalArgumentException("start is after end");
        this.start = start;
        this.endInclusive = endInclusive;
    }

    boolean contains(T value) {
        return start.compareTo(value) <= 0 && value.compareTo(endInclusive) <= 0;
    }
}

var cutoff = new Window<>(LocalDate.of(2026, 11, 2), LocalDate.of(2026, 11, 6));
cutoff.contains(LocalDate.of(2026, 11, 4));   // true (needs the ? super T form for LocalDate)

var limits = new Window<>(1_000L, 50_000L);
limits.contains(75_000L);                     // false

